# The rule seems to be:
# 1. Find the background color (most frequent, here it's 3)
# 2. Find rectangular regions (filled or hollow boundaries) of non-background colors
# 3. Each rectangular region gets FILLED with its color, extending over interior
# 4. Remove all noise pixels that are not part of clean rectangular structures

# Let me identify hollow rectangles in the input
# A hollow rectangle has boundary pixels of a color, with interior being noise/background

def find_hollow_rectangles(grid):
    """Find rectangles that have a boundary of a single color."""
    height = len(grid)
    width = len(grid[0])
    hollow_rects = []

    # Find all pixels of each non-background color and their bounding boxes
    for color in [2, 5, 6, 7, 8]:
        pixels = []
        for r in range(height):
            for c in range(width):
                if grid[r][c] == color:
                    pixels.append((r, c))

        if not pixels:
            continue

        min_r = min(p[0] for p in pixels)
        max_r = max(p[0] for p in pixels)
        min_c = min(p[1] for p in pixels)
        max_c = max(p[1] for p in pixels)

        # Check boundary: all rectangles on boundary should be this color
        boundary_ok = True
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if r in [min_r, max_r] or c in [min_c, max_c]:
                    if grid[r][c] != color:
                        boundary_ok = False
                        break
            if not boundary_ok:
                break

        if boundary_ok:
            # Check interior: interior can have noise or background
            interior_pixels = []
            for r in range(min_r + 1, max_r):
                for c in range(min_c + 1, max_c):
                    if grid[r][c] != color and grid[r][c] != 3:  # noise in interior
                        interior_pixels.append((r, c))

            hollow_rects.append({
                'color': color,
                'r': min_r, 'c': min_c,
                'h': max_r - min_r + 1,
                'w': max_c - min_c + 1,
                'interior_noise': len(interior_pixels)
            })

    return hollow_rects

