import json
from collections import deque, defaultdict

def get_components(grid):
    """4-connected component finding for each color"""
    rows = len(grid)
    cols = len(grid[0])
    vis = [[False]*cols for _ in range(rows)]
    components = defaultdict(list)

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color in [0, 3]:
                continue

            if not vis[r][c]:
                component = []
                q = deque([(r, c)])
                vis[r][c] = True

                while q:
                    cr, cc = q.popleft()
                    component.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not vis[nr][nc] and grid[nr][nc] == color:
                                vis[nr][nc] = True
                                q.append((nr, nc))

                if component:
                    min_r = min(x[0] for x in component)
                    max_r = max(x[0] for x in component)
                    min_c = min(x[1] for x in component)
                    max_c = max(x[1] for x in component)
                    components[color].append(((min_r, max_r, min_c, max_c), component))

    return components

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    components = get_components(grid)

    # Process each color with its bounding box
    for color, bboxes in components.items():
        for (min_r, max_r, min_c, max_c), cells in bboxes:
            # Fill entire bounding box
            for r in range(min_r, max_r + 1):
                for c in range(min_c, max_c + 1):
                    result[r][c] = color

    return result

